def _load_proxies(self):
        """Load proxies from configuration."""
        # Try to load from .proxy.yaml (merged into settings by Dynaconf)
        proxy_pool = settings.get("proxies.pool", [])

        if not proxy_pool:
            logger.warning("[ProxyManager] No proxies configured. Proxy functionality will be disabled.")
            return

        for proxy_string in proxy_pool:
            try:
                # Parse proxy string: host:port:username:password
                parts = proxy_string.split(":")
                if len(parts) == 4:
                    host, port, username, password = parts
                    proxy_info = ProxyInfo(host=host, port=int(port), username=username, password=password)
                    self.proxies.append(proxy_info)
                    logger.debug("[ProxyManager] Loaded proxy: %s:%s", host, port)
                else:
                    safe_proxy = ":".join(proxy_string.split(":")[:2])
                    logger.warning("[ProxyManager] Invalid proxy format: %s", safe_proxy)
            except (ValueError, IndexError) as e:
                safe_proxy = ":".join(proxy_string.split(":")[:2])
                logger.error("[ProxyManager] Failed to parse proxy '%s': %s", safe_proxy, e)

        logger.debug("[ProxyManager] Loaded %d proxies from configuration", len(self.proxies))

