        """Save cookies to JSON file for persistence across browser sessions."""
        if not self.driver:
            return

        try:
            # Get cookies before any cleanup operations
            # This must happen while browser connection is still active
            cookies = self.driver.get_cookies()
            if cookies:
                with open(self._cookies_file, "w") as f:
                    json.dump(cookies, f, indent=2)
                logger.debug(f"Saved {len(cookies)} cookies to {self._cookies_file}")
            else:
